INSERT INTO `yayasans` (`id`, `nama_yayasan`, `kode_yayasan`, `penanggung_jawab`, `telepon`, `alamat`, `logo_yayasan`, `landing_content`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Yayasan Pendidikan Al-Hikmah 1', 'YAH2', NULL, '0341-551122', 'Jl. Veteran No. 45, Malang', NULL, '{\"tk_desc\": \"Program TK berfokus pada pengembangan karakter, motorik, sosial, dan kesiapan sekolah.\", \"tk_misi\": \"Pembelajaran berbasis bermain ramah anak.\", \"tk_visi\": \"Membentuk anak usia dini yang cerdas, mandiri, dan berakhlak mulia.\", \"template\": \"ocean\", \"tk_title\": \"Taman Kanak-Kanak (TK)\", \"paud_desc\": \"Program PAUD stimulasi usia golden age dengan lingkungan belajar yang hangat.\", \"paud_misi\": \"Aktivitas motorik dan sosialisasi sejak usia dini.\", \"paud_visi\": \"Menjadi wadah stimulasi tumbuh kembang balita yang aman dan menyenangkan.\", \"akreditasi\": \"A\", \"badge_text\": null, \"card1_desc\": \"Anak belajar merawat tanaman sendiri.\", \"card2_desc\": \"Metode Montessori, anak memilih aktivitasnya.\", \"hero_title\": \"TK Permata Al-Hikmah Modern\", \"paud_title\": \"Pendidikan Anak Usia Dini (PAUD)\", \"site_title\": \"Yayasan Pendidikan Al-Hikmah 1\", \"card1_title\": \"Bermain aktif\", \"card2_title\": \"Calistung dasar\", \"card3_title\": \"Seni dan musik\", \"cabang_title\": \"Cabang Sekolah di Bawah Yayasan\", \"galeri_1_tag\": \"Kreativitas & Motorik\", \"galeri_2_tag\": \"Karakter & Keagamaan\", \"galeri_3_tag\": \"Ekstrakurikuler\", \"galeri_4_tag\": \"Area Bermain Outbound\", \"galeri_5_tag\": \"Pentas Seni & Field Trip\", \"galeri_6_tag\": \"Sains & Eksplorasi\", \"galeri_title\": \"Galeri Kegiatan & Fasilitas Unggulan\", \"hero_title_1\": \"Ciptakan Generasi Tanggap\", \"hero_title_2\": \"Cerdas & Ceria\", \"profil_title\": \"Kenali Lebih Dekat\", \"whatsapp_cta\": \"0341-551122\", \"yayasan_desc\": \"Yayasan kami berkomitmen penuh untuk mencetak generasi Islami yang unggul.\", \"yayasan_misi\": \"Menyelenggarakan proses pembelajaran yang berkualitas.\", \"yayasan_visi\": \"Mewujudkan lembaga pendidikan yang berpijak pada penanaman aqidah Islam.\", \"alamat_tampil\": \"Jl. Veteran No. 45, Malang\", \"galeri_1_desc\": \"Mewarnai, meronce, menyusun balok, dan melatih motorik halus dengan metode bermain bermakna.\", \"galeri_2_desc\": \"Hafalan surat-surat pendek juz 30, doa harian, dan pengenalan adab sopan santun sejak dini.\", \"galeri_3_desc\": \"Melatih kekompakan, rasa percaya diri, dan kepekaan musikalitas anak melalui ekskul pilihan.\", \"galeri_4_desc\": \"Fasilitas playground indoor & outdoor yang aman untuk melatih ketangkasan serta motorik kasar.\", \"galeri_5_desc\": \"Kunjungan profesi edukatif serta panggung tahunan untuk melatih keberanian anak tampil di depan publik.\", \"galeri_6_desc\": \"Mengenalkan logika fenomena alam dan rasa ingin tahu ilmiah melalui percobaan sederhana yang aman.\", \"hero_subtitle\": \"Membentuk Generasi Rabbani Dan Tanggap\", \"tahun_berdiri\": null, \"yayasan_title\": \"Yayasan Pendidikan Al-Hikmah 2\", \"galeri_1_title\": \"Eksplorasi Belajar & Sensorik\", \"galeri_2_title\": \"Tahfidz Cilik & Pembiasaan Doa\", \"galeri_3_title\": \"Minat Bakat & Drumband Cilik\", \"galeri_4_title\": \"Taman Bermain Aman & Asri\", \"galeri_5_title\": \"Panggung Apresiasi & Wisata Edukasi\", \"galeri_6_title\": \"Eksperimen Sains Anak Usia Dini\", \"cabang_btn_text\": \"Daftar ke Sekolah Ini →\", \"cabang_pill_tag\": \"Unit Pendidikan\", \"cabang_subtitle\": \"Pilih cabang TK / PAUD terdekat dengan domisili Anda untuk melihat informasi kuota dan mendaftarkan anak Anda.\", \"card1_title_nat\": \"Bermain aktif\", \"card2_title_nat\": \"Calistung dasar\", \"galeri_pill_tag\": \"Aktivitas & Fasilitas\", \"galeri_subtitle\": \"Dokumentasi nyata keseruan belajar, bermain, pembiasaan ibadah, dan eksplorasi bakat anak-anak di sekolah kami.\", \"hero_badge_desc\": \"Membimbing motorik, logika, & adab islami sejak usia dini.\", \"jumlah_pengajar\": \"18\", \"profil_subtitle\": \"Pelajari lebih lanjut tentang institusi dan program unggulan kami untuk putra-putri Anda.\", \"show_hero_badge\": \"1\", \"tk_profile_name\": \"Kepala Sekolah TK\", \"hero_badge_title\": \"Pendidikan Holistik Ramah Anak\", \"tk_profile_title\": \"Kepala TK\", \"paud_profile_name\": \"Pengelola PAUD\", \"paud_profile_title\": \"Kepala PAUD\", \"yayasan_profile_name\": \"Pimpinan Yayasan\", \"yayasan_profile_title\": \"Ketua Yayasan\"}', 'aktif', '2026-08-17 05:29:32', '2026-08-26 21:05:39'),
(2, 'Yayasan Bina Insani Ceria', 'YBIC', NULL, '0341-778899', 'Jl. Soekarno Hatta No. 88, Malang', NULL, '{\"tk_desc\": \"Program TK berfokus pada pengembangan karakter, motorik, sosial, dan kesiapan sekolah.\", \"tk_misi\": \"Pembelajaran berbasis bermain ramah anak.\", \"tk_visi\": \"Membentuk anak usia dini yang cerdas, mandiri, dan berakhlak mulia.\", \"template\": \"natural\", \"tk_title\": \"Taman Kanak-Kanak (TK)\", \"paud_desc\": \"Program PAUD stimulasi usia golden age dengan lingkungan belajar yang hangat.\", \"paud_misi\": \"Aktivitas motorik dan sosialisasi sejak usia dini.\", \"paud_visi\": \"Menjadi wadah stimulasi tumbuh kembang balita yang aman dan menyenangkan.\", \"akreditasi\": \"A\", \"badge_text\": null, \"card1_desc\": \"Anak belajar merawat tanaman sendiri.\", \"card2_desc\": \"Metode Montessori, anak memilih aktivitasnya.\", \"hero_title\": null, \"paud_title\": \"Pendidikan Anak Usia Dini (PAUD)\", \"site_title\": \"Yayasan Bina Insani Ceria\", \"card1_title\": \"Bermain aktif\", \"card2_title\": \"Calistung dasar\", \"card3_title\": \"Seni dan musik\", \"hero_title_1\": \"Ciptakan Generasi\", \"hero_title_2\": \"Cerdas & Ceria\", \"profil_title\": \"Kenali Lebih Dekat\", \"whatsapp_cta\": \"0341-778899\", \"yayasan_desc\": \"Yayasan kami berkomitmen penuh untuk mencetak generasi Islami yang unggul.\", \"yayasan_misi\": \"Menyelenggarakan proses pembelajaran yang berkualitas.\", \"yayasan_visi\": \"Mewujudkan lembaga pendidikan yang berpijak pada penanaman aqidah Islam.\", \"alamat_tampil\": \"Jl. Soekarno Hatta No. 88, Malang\", \"hero_subtitle\": \"Memberikan pendidikan terbaik untuk generasi masa depan dengan fasilitas lengkap dan tenaga pengajar profesional.\", \"tahun_berdiri\": null, \"yayasan_title\": \"Yayasan Bina Insani Ceria\", \"card1_title_nat\": \"Kelas berkebun\", \"card2_title_nat\": \"Eksplorasi mandiri\", \"jumlah_pengajar\": \"18\", \"profil_subtitle\": \"Pelajari lebih lanjut tentang institusi dan program unggulan kami untuk putra-putri Anda.\", \"tk_profile_name\": \"Kepala Sekolah TK\", \"tk_profile_title\": \"Kepala TK\", \"paud_profile_name\": \"Pengelola PAUD\", \"paud_profile_title\": \"Kepala PAUD\", \"yayasan_profile_name\": \"Pimpinan Yayasan\", \"yayasan_profile_title\": \"Ketua Yayasan\"}', 'aktif', '2026-08-17 05:29:32', '2026-08-18 19:19:44');

